+import { readFileSync } from "node:fs";
+import { fileURLToPath } from "node:url";
+
+type VerifiedTarget = {
+  status: "verified";
+  testedVersions: string[];
+};
+
+type TargetRegistry = Record<string, VerifiedTarget | { status: string }>;
+
+const registryPath = fileURLToPath(new URL("./target-compatibility.json", import.meta.url));
+
+function readRegistry(): TargetRegistry {
+  return JSON.parse(readFileSync(registryPath, "utf8")) as TargetRegistry;
+}
+
+/** Return registry claims by default, or explicit candidate versions for one invocation. */
+export function targetVersions(packageName: string, candidates: readonly string[] = []): string[] {
+  const versions = candidates.length > 0 ? [...candidates] : readRegistry()[packageName];
+  if (!versions || versions.status !== "verified" || !Array.isArray(versions.testedVersions)) {
+    throw new Error(`Target ${packageName} does not have verified release versions`);
+  }
+  if (versions.testedVersions.length === 0) {
+    throw new Error(`Target ${packageName} has no tested release versions`);
+  }
+  return candidates.length > 0 ? [...candidates] : [...versions.testedVersions];
+}
+
+/** Read explicit command-line candidates, falling back to the registry's tested versions. */
+export function commandTargetVersions(packageName: string): string[] {
+  return targetVersions(packageName, process.argv.slice(2));
+}
*** Add File: /Users/dwahl/Scripts/pantoken/scripts/release/target-versions.test.ts
+import { expect, test } from "vite-plus/test";
+import { targetVersions } from "./target-versions.ts";
+
+test("reads the verified versions from the target registry", () => {
+  expect(targetVersions("@pantoken/postcss")).toEqual([
+    "8.0.0",
+    "8.0.9",
+    "8.1.14",
+    "8.2.15",
+    "8.3.11",
+    "8.4.49",
+    "8.5.28",
+  ]);
+});
+
+test("uses explicit candidates without changing the registry claim", () => {
+  const candidates = ["8.5.29"];
+  expect(targetVersions("@pantoken/postcss", candidates)).toEqual(candidates);
+  expect(targetVersions("@pantoken/postcss")).toContain("8.5.28");
+});
+
+test("rejects unverified targets", () => {
+  expect(() => targetVersions("@pantoken/email")).toThrow(
+    "does not have verified release versions",
+  );
+});
*** End Patch","explanation":"Add a registry-backed version selector and focused tests."}

